package com.example.urlshortener.dto;import javax.validation.constraints.NotBlank;import javax.validation.constraints.Pattern;public class ShortenRequest {    @NotBlank(message = "Original URL cannot be empty")    @Pattern(regexp = "^(https?|ftp|file)://[-a-zA-Z0-9+&@#/%?=~_|!:,.;]*[-a-zA-Z0-9+&@#/%=~_|]",            message = "Invalid URL format")    private String longUrl;    public ShortenRequest() {    }    public ShortenRequest(String longUrl) {        this.longUrl = longUrl;    }    public String getLongUrl() {        return longUrl;    }    public void setLongUrl(String longUrl) {        this.longUrl = longUrl;    }}